use std::collections::HashMap;

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Exp {
    Const(i64),
    Var(String),
    Plus(Box<Exp>, Box<Exp>),
    Mult(Box<Exp>, Box<Exp>),
}

/// Evaluate an expression under a store. Missing variables evaluate to -1.
pub fn eval(e: &Exp, store: &HashMap<String, i64>) -> i64 {
    match e {
        Exp::Const(c) => *c,
        Exp::Var(name) => *store.get(name).unwrap_or(&-1),
        Exp::Plus(a, b) => eval(a, store) + eval(b, store),
        Exp::Mult(a, b) => eval(a, store) * eval(b, store),
    }
}

/// Perform a single-step peephole optimization at the root (does not recurse).
pub fn optimize(e: Exp) -> Exp {
    match e {
        Exp::Mult(a, b) => match (&*a, &*b) {
            // Absorbing element
            (Exp::Const(0), _) | (_, Exp::Const(0)) => Exp::Const(0),

            // Neutral element
            (Exp::Const(1), rhs) => rhs.clone(),
            (lhs, Exp::Const(1)) => lhs.clone(),

            // Constant folding
            (Exp::Const(x), Exp::Const(y)) => Exp::Const(x * y),

            // Otherwise unchanged
            _ => Exp::Mult(a, b),
        },

        Exp::Plus(a, b) => match (&*a, &*b) {
            // Neutral element
            (Exp::Const(0), rhs) => rhs.clone(),
            (lhs, Exp::Const(0)) => lhs.clone(),

            // Constant folding
            (Exp::Const(x), Exp::Const(y)) => Exp::Const(x + y),

            // Otherwise unchanged
            _ => Exp::Plus(a, b),
        },

        // Otherwise unchanged
        other => other,
    }
}

/// Checks (for a given expression and store) that optimization preserves evaluation.
///
/// Note: The original problem asks for a proof for all expressions and stores; in
/// executable Rust we provide a boolean checker for the stated property.
pub fn optimize_correct(e: Exp, s: &HashMap<String, i64>) -> bool {
    let v1 = eval(&e, s);
    let e_opt = optimize(e);
    let v2 = eval(&e_opt, s);
    v1 == v2
}